diffs.patch:
Index: index.html
===================================================================
--- index.html	
+++ index.html	
@@ -0,0 +1,518 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8">
+<meta name="viewport" content="width=device-width, initial-scale=1.0">
+<title>STRIKE PROTOCOL — Tactical Arena Ops</title>
+<style>
+  :root{
+    --bg:#0a0e14; --panel:rgba(10,16,24,.82); --line:rgba(120,180,150,.18);
+    --accent:#7CFFB2; --amber:#ffc857; --red:#ff5d5d; --text:#dfe9e4; --dim:#8fa39a;
+  }
+  *{margin:0;padding:0;box-sizing:border-box}
+  html,body{width:100%;height:100%;background:var(--bg);overflow:hidden;font-family:"Segoe UI",Inter,system-ui,-apple-system,sans-serif;color:var(--text);user-select:none}
+  #wrap{position:fixed;inset:0}
+  canvas{display:block;width:100%;height:100%;cursor:none;background:#0a0e14}
+  /* ---- HUD (edges only, playfield center stays clean) ---- */
+  #hud{position:absolute;inset:0;pointer-events:none;z-index:5}
+  .hud-top{position:absolute;top:0;left:0;right:0;display:flex;justify-content:center;padding-top:12px}
+  #objective{pointer-events:none;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:8px 18px;text-align:center;backdrop-filter:blur(8px);min-width:340px}
+  #objective .obj-label{font-size:10px;letter-spacing:.22em;color:var(--accent);font-weight:700}
+  #objective .obj-text{font-size:14px;font-weight:600;margin-top:2px}
+  #objective .obj-sub{font-size:11px;color:var(--dim);margin-top:2px}
+  #wavebar{height:4px;background:rgba(255,255,255,.08);border-radius:4px;margin-top:7px;overflow:hidden}
+  #wavefill{height:100%;width:0%;background:linear-gradient(90deg,var(--accent),#3ddc84);transition:width .4s}
+  .hud-tl{position:absolute;top:12px;left:12px;display:flex;flex-direction:column;gap:8px}
+  #minimap{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:8px;backdrop-filter:blur(8px)}
+  #minimap canvas{width:150px;height:100px;cursor:default}
+  #killfeed{display:flex;flex-direction:column;gap:4px;max-width:230px}
+  .kf{font-size:11px;background:rgba(0,0,0,.55);border:1px solid var(--line);border-left:3px solid var(--accent);padding:4px 8px;border-radius:6px;animation:kfin .25s ease-out}
+  @keyframes kfin{from{transform:translateX(-12px);opacity:0}to{transform:none;opacity:1}}
+  .hud-tr{position:absolute;top:12px;right:12px;text-align:right}
+  #score{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:8px 14px;backdrop-filter:blur(8px)}
+  #score .k{font-size:22px;font-weight:800;color:#fff}
+  #score .l{font-size:10px;letter-spacing:.18em;color:var(--dim)}
+  .hud-bl{position:absolute;left:16px;bottom:16px;width:300px}
+  #hp-wrap{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:10px 12px;backdrop-filter:blur(8px)}
+  #hp-row{display:flex;justify-content:space-between;align-items:baseline}
+  #hp-num{font-size:26px;font-weight:800}
+  #hp-label{font-size:10px;letter-spacing:.2em;color:var(--dim)}
+  #hp-bar{height:8px;background:rgba(255,255,255,.1);border-radius:6px;margin-top:6px;overflow:hidden}
+  #hp-fill{height:100%;width:100%;background:linear-gradient(90deg,#3ddc84,var(--accent));transition:width .2s}
+  #hp-fill.low{background:linear-gradient(90deg,#ff3b3b,#ff8a5d)}
+  #stam-bar{height:4px;background:rgba(255,255,255,.08);border-radius:4px;margin-top:6px;overflow:hidden}
+  #stam-fill{height:100%;width:100%;background:#7cc4ff}
+  .hud-br{position:absolute;right:16px;bottom:16px;text-align:right}
+  #ammo{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:8px 18px;backdrop-filter:blur(8px);min-width:150px}
+  #ammo-mag{font-size:34px;font-weight:800;line-height:1}
+  #ammo-res{font-size:14px;color:var(--dim)}
+  #ammo-hint{font-size:10px;letter-spacing:.15em;color:var(--dim);margin-top:2px}
+  #reload-tip{font-size:12px;color:var(--amber);font-weight:700;margin-top:4px;display:none;animation:blink 0.6s infinite alternate}
+  @keyframes blink{from{opacity:1}to{opacity:.4}}
+  #banner{position:absolute;top:26%;left:0;right:0;text-align:center;pointer-events:none;opacity:0;transition:opacity .3s}
+  #banner.show{opacity:1}
+  #banner h2{font-size:52px;letter-spacing:.12em;font-weight:900;text-shadow:0 4px 30px rgba(0,0,0,.8)}
+  #banner p{letter-spacing:.3em;font-size:13px;color:var(--accent);font-weight:700}
+  #hitmarker{position:absolute;left:50%;top:50%;width:28px;height:28px;transform:translate(-50%,-50%);pointer-events:none;opacity:0}
+  #hitmarker span{position:absolute;background:#fff;box-shadow:0 0 6px rgba(255,255,255,.9)}
+  #dmg-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 120px 40px rgba(255,30,30,.55);opacity:0;transition:opacity .15s}
+  #heal-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 100px 20px rgba(124,255,178,.25);opacity:0;transition:opacity .4s}
+  /* ---- Overlays ---- */
+  .overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at center,rgba(8,14,20,.55),rgba(4,7,11,.92));z-index:10;backdrop-filter:blur(3px)}
+  .card{background:rgba(12,19,28,.94);border:1px solid rgba(124,255,178,.22);border-radius:16px;padding:34px 40px;max-width:560px;width:92%;text-align:center;box-shadow:0 20px 80px rgba(0,0,0,.6)}
+  .card .tag{font-size:11px;letter-spacing:.3em;color:var(--accent);font-weight:800}
+  .card h1{font-size:42px;font-weight:900;letter-spacing:.04em;margin:6px 0}
+  .card h1 em{color:var(--accent);font-style:normal}
+  .card p{font-size:14px;color:#b9c8c0;line-height:1.6}
+  .controls{display:grid;grid-template-columns:1fr 1fr;gap:6px 18px;margin:18px 0;text-align:left;font-size:13px}
+  .controls b{display:inline-block;min-width:86px;color:var(--accent);font-family:monospace;font-size:12px}
+  .btn{pointer-events:auto;cursor:pointer;border:none;border-radius:10px;padding:13px 34px;font-size:15px;font-weight:800;letter-spacing:.08em;background:linear-gradient(180deg,#8fffc0,#3ddc84);color:#06110b;transition:transform .08s}
+  .btn:hover{transform:translateY(-1px) scale(1.02)}
+  .btn.ghost{background:transparent;border:1px solid var(--line);color:var(--text);margin-left:8px}
+  .stats{display:flex;gap:18px;justify-content:center;margin:16px 0}
+  .stats div{text-align:center}
+  .stats .v{font-size:26px;font-weight:800}
+  .stats .k{font-size:10px;letter-spacing:.2em;color:var(--dim)}
+  .hidden{display:none!important}
+  #toast{position:absolute;bottom:110px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,.7);border:1px solid var(--line);padding:6px 16px;border-radius:20px;font-size:12px;opacity:0;transition:opacity .3s;pointer-events:none}
+</style>
+</head>
+<body>
+<div id="wrap">
+  <canvas id="game"></canvas>
+  <div id="hud">
+    <div class="hud-top"><div id="objective">
+      <div class="obj-label">◆ OBJECTIVE</div>
+      <div class="obj-text" id="obj-text">Eliminate all hostiles — Wave 1/3</div>
+      <div class="obj-sub" id="obj-sub">Hostiles remaining: 0</div>
+      <div id="wavebar"><div id="wavefill"></div></div>
+    </div></div>
+    <div class="hud-tl">
+      <div id="minimap"><canvas id="mm" width="150" height="100"></canvas></div>
+      <div id="killfeed"></div>
+    </div>
+    <div class="hud-tr"><div id="score"><div class="k" id="kills">0</div><div class="l">CONFIRMED KILLS</div><div class="l" id="timer" style="margin-top:4px;color:var(--accent)">00:00</div></div></div>
+    <div class="hud-bl"><div id="hp-wrap">
+      <div id="hp-row"><span id="hp-label">■ OPERATOR HEALTH</span><span id="hp-num">100</span></div>
+      <div id="hp-bar"><div id="hp-fill"></div></div>
+      <div id="stam-bar"><div id="stam-fill"></div></div>
+    </div></div>
+    <div class="hud-br"><div id="ammo"><span id="ammo-mag">30</span> <span id="ammo-res">/ 90</span><div id="ammo-hint">[R] RELOAD &nbsp; [RMB] AIM</div><div id="reload-tip">RELOADING…</div></div></div>
+    <div id="banner"><p id="banner-sub">WAVE 1</p><h2 id="banner-title">CONTACT!</h2></div>
+    <div id="hitmarker"><span style="left:12px;top:0;width:3px;height:8px;transform:rotate(-45deg)"></span><span style="right:12px;top:0;width:3px;height:8px;transform:rotate(45deg)"></span><span style="left:12px;bottom:0;width:3px;height:8px;transform:rotate(45deg)"></span><span style="right:12px;bottom:0;width:3px;height:8px;transform:rotate(-45deg)"></span></div>
+    <div id="dmg-vignette"></div><div id="heal-vignette"></div>
+    <div id="toast"></div>
+  </div>
+
+  <div class="overlay" id="menu-start">
+    <div class="card">
+      <div class="tag">TACTICAL ARENA OPS // NIGHT RAID</div>
+      <h1>STRIKE <em>PROTOCOL</em></h1>
+      <p>Fast, close-quarters combat. Clear <b>3 waves</b> of hostiles, then <b>reach extraction</b> (green zone). Health regenerates out of combat — keep moving, aim for the head, and don't get surrounded.</p>
+      <div class="controls">
+        <div><b>W A S D</b> Move</div><div><b>MOUSE</b> Aim</div>
+        <div><b>LMB</b> Fire</div><div><b>RMB hold</b> Aim down sights</div>
+        <div><b>SHIFT</b> Sprint</div><div><b>R</b> Reload &nbsp; <b>P</b> Pause</div>
+      </div>
+      <button class="btn" id="btn-start">▶ DEPLOY</button>
+      <p style="margin-top:10px;font-size:11px;color:var(--dim)">Best on desktop · sound on 🔊</p>
+    </div>
+  </div>
+
+  <div class="overlay hidden" id="menu-end">
+    <div class="card">
+      <div class="tag" id="end-tag">MISSION COMPLETE</div>
+      <h1 id="end-title">EXTRACTED <em>ALIVE</em></h1>
+      <p id="end-desc"></p>
+      <div class="stats">
+        <div><div class="v" id="st-kills">0</div><div class="k">KILLS</div></div>
+        <div><div class="v" id="st-time">0:00</div><div class="k">TIME</div></div>
+        <div><div class="v" id="st-acc">0%</div><div class="k">ACCURACY</div></div>
+        <div><div class="v" id="st-wave">1</div><div class="k">WAVE</div></div>
+      </div>
+      <button class="btn" id="btn-restart">↻ REDEPLOY</button>
+    </div>
+  </div>
+
+  <div class="overlay hidden" id="menu-pause">
+    <div class="card"><div class="tag">PAUSED</div><h1>STAND <em>BY</em></h1>
+    <p>Take a breath, operator.</p><br>
+    <button class="btn" id="btn-resume">RESUME</button><button class="btn ghost" id="btn-quit">RESTART</button></div>
+  </div>
+</div>
+<script>
+"use strict";
+/* ============ STRIKE PROTOCOL — self-contained top-down tactical shooter ============ */
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
+const mm=document.getElementById('mm'),mmc=mm.getContext('2d');
+const $=id=>document.getElementById(id);
+let W=0,H=0,DPR=1;
+function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);}
+addEventListener('resize',resize);resize();
+
+// ---------- Audio (procedural, no assets) ----------
+let AC=null;function ac(){if(!AC){try{AC=new (window.AudioContext||window.webkitAudioContext)()}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
+function beep(f,d,type='square',vol=.15,slide=0){const a=ac();if(!a)return;const o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.setValueAtTime(f,a.currentTime);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(20,f+slide),a.currentTime+d);g.gain.setValueAtTime(vol,a.currentTime);g.gain.exponentialRampToValueAtTime(.0001,a.currentTime+d);o.connect(g).connect(a.destination);o.start();o.stop(a.currentTime+d);}
+function noise(d=.12,vol=.25,lp=2500){const a=ac();if(!a)return;const b=a.createBuffer(1,a.sampleRate*d,a.sampleRate),ch=b.getChannelData(0);for(let i=0;i<ch.length;i++)ch[i]=(Math.random()*2-1)*(1-i/ch.length);const s=a.createBufferSource();s.buffer=b;const f=a.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;const g=a.createGain();g.gain.value=vol;s.connect(f).connect(g).connect(a.destination);s.start();}
+const SFX={shoot(){noise(.09,.22,3200);beep(160,.07,'square',.1,-80)},adsShoot(){noise(.1,.26,2000);beep(120,.09,'square',.12,-50)},enemyShoot(){noise(.08,.1,1400);beep(300,.06,'sawtooth',.05,-120)},hit(){beep(900,.05,'square',.08)},kill(){beep(520,.12,'square',.12,260);setTimeout(()=>beep(780,.12,'square',.1,200),70)},hurt(){noise(.2,.3,500);beep(110,.2,'sawtooth',.14,-40)},reload(){beep(400,.06,'square',.09);setTimeout(()=>beep(600,.06,'square',.09),180);setTimeout(()=>beep(800,.08,'square',.1),650)},wave(){beep(220,.3,'sawtooth',.12,220);setTimeout(()=>beep(440,.3,'sawtooth',.1,220),180)},extract(){[523,659,784,1046].forEach((f,i)=>setTimeout(()=>beep(f,.25,'sine',.12),i*130))},click(){beep(700,.05,'square',.08)}};
+
+// ---------- World ----------
+const WORLD={w:1800,h:1200};
+const obstacles=[
+  {x:300,y:300,w:180,h:40},{x:700,y:200,w:40,h:220},{x:1050,y:280,w:220,h:44},
+  {x:1400,y:180,w:44,h:260},{x:250,y:700,w:44,h:240},{x:500,y:800,w:240,h:44},
+  {x:900,y:650,w:60,h:260},{x:1150,y:750,w:260,h:44},{x:1450,y:700,w:44,h:260},
+  {x:800,y:450,w:200,h:36},{x:200,y:450,w:120,h:120},{x:1500,y:450,w:140,h:110},
+];
+const extractZone={x:WORLD.w/2-90,y:WORLD.h-170,w:180,h:110};
+function collideCircle(x,y,r){
+  x=Math.max(r,Math.min(WORLD.w-r,x));y=Math.max(r,Math.min(WORLD.h-r,y));
+  for(const o of obstacles){
+    const cx=Math.max(o.x,Math.min(x,o.x+o.w)),cy=Math.max(o.y,Math.min(y,o.y+o.h));
+    const dx=x-cx,dy=y-cy;if(dx*dx+dy*dy<r*r){
+      const d=Math.hypot(dx,dy)||.001;
+      if(d<r){x=cx+dx/d*r;y=cy+dy/d*r;}
+    }
+  }
+  return {x,y};
+}
+function lineBlocked(x1,y1,x2,y2){
+  for(const o of obstacles){
+    if(segRect(x1,y1,x2,y2,o))return true;
+  }return false;
+}
+function segRect(x1,y1,x2,y2,r){
+  // sample-based LOS (cheap + robust)
+  const steps=12;
+  for(let i=0;i<=steps;i++){const t=i/steps,x=x1+(x2-x1)*t,y=y1+(y2-y1)*t;
+    if(x>r.x&&x<r.x+r.w&&y>r.y&&y<r.y+r.h)return true;}
+  return false;
+}
+
+// ---------- State ----------
+const G={mode:'menu',wave:0,maxWaves:3,enemies:[],bullets:[],ebullets:[],parts:[],shells:[],floats:[],
+  kills:0,shots:0,hits:0,time:0,shake:0,bannerT:0,extractActive:false,waveDelay:0,spawnQueue:[]};
+const P={x:WORLD.w/2,y:WORLD.h/2+200,r:14,hp:100,maxhp:100,angle:0,speed:265,sprint:1.55,stam:100,
+  mag:30,magSize:30,reserve:120,reloading:0,fireCd:0,ads:false,lastHurt:-99,alive:true,muzzle:0,recoil:0};
+const keys={};let mouse={x:W/2,y:H/2,down:false,rdown:false};
+let cam={x:0,y:0,zoom:1};
+
+addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;
+  if(e.key.toLowerCase()==='r')startReload();
+  if(e.key.toLowerCase()==='p'||e.key==='Escape')togglePause();});
+addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
+canvas.addEventListener('mousemove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;});
+canvas.addEventListener('mousedown',e=>{ac();if(e.button===0)mouse.down=true;if(e.button===2)mouse.rdown=true;});
+addEventListener('mouseup',e=>{if(e.button===0)mouse.down=false;if(e.button===2)mouse.rdown=false;});
+addEventListener('contextmenu',e=>e.preventDefault());
+
+function startReload(){if(G.mode!=='play'||P.reloading>0||P.mag===P.magSize||P.reserve<=0)return;P.reloading=1.25;SFX.reload();$('reload-tip').style.display='block';}
+function toast(t){const el=$('toast');el.textContent=t;el.style.opacity=1;clearTimeout(el._t);el._t=setTimeout(()=>el.style.opacity=0,1800);}
+function feed(t){const kf=$('killfeed');const d=document.createElement('div');d.className='kf';d.textContent=t;kf.prepend(d);while(kf.children.length>4)kf.lastChild.remove();setTimeout(()=>{d.style.opacity='0';d.style.transition='opacity .5s';setTimeout(()=>d.remove(),500)},3500);}
+function banner(sub,title){$('banner-sub').textContent=sub;$('banner-title').textContent=title;$('banner').classList.add('show');clearTimeout(banner._t);banner._t=setTimeout(()=>$('banner').classList.remove('show'),2200);}
+function hitmarker(kill){const h=$('hitmarker');h.style.opacity=1;h.style.transform=`translate(-50%,-50%) scale(${kill?1.5:1}) rotate(${kill?45:0}deg)`;clearTimeout(h._t);h._t=setTimeout(()=>h.style.opacity=0,kill?220:110);}
+
+// ---------- Waves ----------
+function waveComp(n){return n===1?{rush:3,troop:2}:n===2?{rush:4,troop:4}:n===3?{rush:5,troop:6}:{rush:3,troop:2};}
+function startWave(n){
+  G.wave=n;const c=waveComp(n);
+  G.spawnQueue=[];
+  for(let i=0;i<c.rush;i++)G.spawnQueue.push('rush');
+  for(let i=0;i<c.troop;i++)G.spawnQueue.push('troop');
+  G.spawnQueue.sort(()=>Math.random()-.5);
+  G.waveDelay=.5;SFX.wave();banner('WAVE '+n+' / '+G.maxWaves,n===3?'FINAL STAND':'CONTACT!');
+  $('obj-text').textContent=`Eliminate all hostiles — Wave ${n}/${G.maxWaves}`;
+}
+function spawnEnemy(type){
+  // spawn at edges away from player
+  let x,y,tries=0;
+  do{const e=Math.floor(Math.random()*4);
+    if(e===0){x=Math.random()*WORLD.w;y=40;}else if(e===1){x=Math.random()*WORLD.w;y=WORLD.h-40;}
+    else if(e===2){x=40;y=Math.random()*WORLD.h;}else{x=WORLD.w-40;y=Math.random()*WORLD.h;}
+    tries++;
+  }while(Math.hypot(x-P.x,y-P.y)<420&&tries<20);
+  if(type==='rush')G.enemies.push({type,x,y,r:13,hp:45,maxhp:45,speed:170+Math.random()*40+ G.wave*12,atkCd:0,flash:0});
+  else G.enemies.push({type,x,y,r:14,hp:70,maxhp:70,speed:115+Math.random()*20,fireCd:1+Math.random()*2,strafe:Math.random()<.5?1:-1,strafeT:Math.random()*2,flash:0});
+}
+function resetGame(){
+  G.enemies=[];G.bullets=[];G.ebullets=[];G.parts=[];G.shells=[];G.floats=[];G.spawnQueue=[];
+  G.kills=0;G.shots=0;G.hits=0;G.time=0;G.extractActive=false;G.mode='play';
+  Object.assign(P,{x:WORLD.w/2,y:WORLD.h/2+200,hp:100,mag:30,reserve:120,reloading:0,fireCd:0,ads:false,lastHurt:-99,alive:true,stam:100,recoil:0});
+  $('menu-start').classList.add('hidden');$('menu-end').classList.add('hidden');$('menu-pause').classList.add('hidden');
+  $('killfeed').innerHTML='';
+  startWave(1);
+}
+$('btn-start').onclick=()=>{SFX.click();resetGame();};
+$('btn-restart').onclick=()=>{SFX.click();resetGame();};
+$('btn-resume').onclick=()=>{G.mode='play';$('menu-pause').classList.add('hidden');};
+$('btn-quit').onclick=()=>{resetGame();};
+function togglePause(){
+  if(G.mode==='play'){G.mode='pause';$('menu-pause').classList.remove('hidden');}
+  else if(G.mode==='pause'){G.mode='play';$('menu-pause').classList.add('hidden');}
+}
+function endGame(win){
+  G.mode=win?'win':'lose';
+  const acc=G.shots?Math.round(G.hits/G.shots*100):0;
+  const mmss=fmtTime(G.time);
+  $('end-tag').textContent=win?'MISSION COMPLETE':'KIA — MISSION FAILED';
+  $('end-title').innerHTML=win?'EXTRACTED <em>ALIVE</em>':'FLAT<em>LINED</em>';
+  $('end-desc').textContent=win?`All waves cleared and extraction reached with ${Math.round(P.hp)} HP to spare. Clean work, operator.`:`You fell on wave ${G.wave} with ${G.kills} confirmed kills. Redeploy and keep moving — standing still gets you killed.`;
+  $('st-kills').textContent=G.kills;$('st-time').textContent=mmss;$('st-acc').textContent=acc+'%';$('st-wave').textContent=G.wave+'/'+G.maxWaves;
+  $('menu-end').classList.remove('hidden');
