+}
+function fmtTime(t){const m=Math.floor(t/60),s=Math.floor(t%60);return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');}
+
+// ---------- Combat helpers ----------
+function fireBullet(){
+  const spread=P.ads?0.022:0.065+P.recoil*0.02;
+  const a=P.angle+(Math.random()-.5)*2*spread+ (P.ads?0:(Math.random()-.5)*0.03);
+  const sp=1150;
+  G.bullets.push({x:P.x+Math.cos(P.angle)*22,y:P.y+Math.sin(P.angle)*22,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,life:.8,dmg:P.ads?34:26});
+  P.mag--;G.shots++;P.muzzle=.06;P.recoil=Math.min(1,P.recoil+.22);G.shake=Math.min(6,G.shake+(P.ads?1:2));
+  P.shells.push({x:P.x,y:P.y,vx:Math.cos(P.angle+Math.PI/2)*(80+Math.random()*60),vy:Math.sin(P.angle+Math.PI/2)*(80+Math.random()*60),rot:Math.random()*6,vr:8,life:.7});
+  muzzleParts(P.x+Math.cos(P.angle)*26,P.y+Math.sin(P.angle)*26,P.angle);
+  if(P.ads)SFX.adsShoot();else SFX.shoot();
+  if(P.mag===0)startReload();
+}
+function muzzleParts(x,y,a){for(let i=0;i<5;i++)G.parts.push({x,y,vx:Math.cos(a+(Math.random()-.5))*(200+Math.random()*250),vy:Math.sin(a+(Math.random()-.5))*(200+Math.random()*250),life:.18+Math.random()*.12,max:.3,c:'#ffd97c',r:2.5});}
+function blood(x,y,n=8,c='#ff5d5d'){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=60+Math.random()*220;G.parts.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.4+Math.random()*.3,max:.7,c,r:1+Math.random()*2.5});}}
+function spark(x,y){for(let i=0;i<6;i++){const a=Math.random()*Math.PI*2,s=100+Math.random()*250;G.parts.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25,max:.25,c:'#ffe9a8',r:1.5});}}
+function floatText(x,y,t,c='#fff'){G.floats.push({x,y,t,c,life:.9});}
+
+// ---------- Update ----------
+let last=performance.now();
+function loop(now){
+  requestAnimationFrame(loop);
+  let dt=Math.min(.033,(now-last)/1000);last=now;
+  if(G.mode==='play')update(dt);
+  render(dt);
+  updateHUD();
+}
+function update(dt){
+  G.time+=dt;
+  // aim
+  const wx=cam.x+mouse.x, wy=cam.y+mouse.y;
+  P.angle=Math.atan2(wy-P.y,wx-P.x);
+  P.ads=mouse.rdown&&P.reloading<=0;
+  // move
+  let mx=(keys['d']||keys['arrowright']?1:0)-(keys['a']||keys['arrowleft']?1:0);
+  let my=(keys['s']||keys['arrowdown']?1:0)-(keys['w']||keys['arrowup']?1:0);
+  const moving=(mx||my);
+  if(moving){const l=Math.hypot(mx,my);mx/=l;my/=l;}
+  const wantSprint=(keys['shift'])&&moving&&!P.ads;
+  let speed=P.speed*(P.ads?.55:1);
+  if(wantSprint&&P.stam>1){speed*=P.sprint;P.stam=Math.max(0,P.stam-38*dt);}else{P.stam=Math.min(100,P.stam+26*dt);}
+  const nx=P.x+mx*speed*dt, ny=P.y+my*speed*dt;
+  const c1=collideCircle(nx,P.y,P.r);const c2=collideCircle(c1.x,ny,P.r);P.x=c2.x;P.y=c2.y;
+  // reload / fire
+  if(P.reloading>0){P.reloading-=dt;if(P.reloading<=0){const need=P.magSize-P.mag,take=Math.min(need,P.reserve);P.mag+=take;P.reserve-=take;$('reload-tip').style.display='none';}}
+  P.fireCd-=dt;P.muzzle-=dt;P.recoil=Math.max(0,P.recoil-dt*3);
+  if(mouse.down&&P.reloading<=0&&P.fireCd<=0&&P.mag>0&&P.alive){fireBullet();P.fireCd=P.ads?0.13:0.115;}
+  // health regen (CoD-style)
+  if(G.time-P.lastHurt>4&&P.hp<P.maxhp){P.hp=Math.min(P.maxhp,P.hp+26*dt);$('heal-vignette').style.opacity=.7;}else $('heal-vignette').style.opacity=0;
+  // staggered spawns
+  if(G.spawnQueue.length){G.waveDelay-=dt;if(G.waveDelay<=0){spawnEnemy(G.spawnQueue.shift());G.waveDelay=.45;}}
+  // bullets
+  for(let i=G.bullets.length-1;i>=0;i--){const b=G.bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;
+    let dead=b.life<=0||b.x<0||b.y<0||b.x>WORLD.w||b.y>WORLD.h;
+    if(!dead)for(const o of obstacles){if(b.x>o.x&&b.x<o.x+o.w&&b.y>o.y&&b.y<o.y+o.h){spark(b.x,b.y);dead=true;break;}}
+    if(!dead)for(let j=G.enemies.length-1;j>=0;j--){const e=G.enemies[j];
+      if(Math.hypot(b.x-e.x,b.y-e.y)<e.r+3){
+        const head=Math.hypot(b.x-e.x,b.y-e.y)<6;
+        e.hp-=b.dmg*(head?1.8:1);e.flash=.08;G.hits++;SFX.hit();blood(b.x,b.y,head?10:6);
+        floatText(e.x,e.y-18,(head?'CRIT ':'')+Math.round(b.dmg*(head?1.8:1)),head?'#ffc857':'#fff');
+        if(e.hp<=0){killEnemy(j);}else hitmarker(false);
+        dead=true;break;}}
+    if(dead)G.bullets.splice(i,1);
+  }
+  // enemies
+  for(let j=G.enemies.length-1;j>=0;j--){const e=G.enemies[j];e.flash-=dt;
+    const dx=P.x-e.x,dy=P.y-e.y,d=Math.hypot(dx,dy)||1;
+    const blocked=lineBlocked(e.x,e.y,P.x,P.y);
+    if(e.type==='rush'){
+      let s=e.speed*(blocked?0.9:1.15);
+      const p=collideCircle(e.x+dx/d*s*dt,e.y+dy/d*s*dt,e.r);e.x=p.x;e.y=p.y;
+      e.atkCd-=dt;
+      if(d<30&&e.atkCd<=0){e.atkCd=.8;damagePlayer(12,'Rusher clawed you');blood(P.x,P.y,6);}
+    }else{
+      e.strafeT-=dt;if(e.strafeT<=0){e.strafeT=1+Math.random()*2;e.strafe*=-1;}
+      e.fireCd-=dt;
+      let mvx=0,mvy=0;
+      if(d>380||blocked){mvx=dx/d;mvy=dy/d;}
+      else if(d<240){mvx=-dx/d;mvy=-dy/d;}
+      else{mvx=-dy/d*e.strafe;mvy=dx/d*e.strafe;}
+      const p=collideCircle(e.x+mvx*e.speed*dt,e.y+mvy*e.speed*dt,e.r);e.x=p.x;e.y=p.y;
+      if(!blocked&&d<560&&e.fireCd<=0){e.fireCd=1.3+Math.random()*1.2;
+        const a=Math.atan2(dy,dx)+(Math.random()-.5)*.12;
+        G.ebullets.push({x:e.x,y:e.y,vx:Math.cos(a)*430,vy:Math.sin(a)*430,life:1.6});SFX.enemyShoot();}
+    }
+    // separation
+    for(const o of G.enemies){if(o===e)continue;const sx=e.x-o.x,sy=e.y-o.y,sd=Math.hypot(sx,sy);if(sd>0&&sd<28){e.x+=sx/sd*30*dt;e.y+=sy/sd*30*dt;}}
+  }
+  // enemy bullets
+  for(let i=G.ebullets.length-1;i>=0;i--){const b=G.ebullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;
+    let dead=b.life<=0;
+    if(!dead)for(const o of obstacles){if(b.x>o.x&&b.x<o.x+o.w&&b.y>o.y&&b.y<o.y+o.h){dead=true;break;}}
+    if(!dead&&Math.hypot(b.x-P.x,b.y-P.y)<P.r+2){damagePlayer(9,'Trooper fire');dead=true;}
+    if(dead)G.ebullets.splice(i,1);
+  }
+  // particles
+  for(let i=G.parts.length-1;i>=0;i--){const p=G.parts[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.92;p.vy*=.92;p.life-=dt;if(p.life<=0)G.parts.splice(i,1);}
+  for(let i=P.shells.length-1;i>=0;i--){const s=P.shells[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.vx*=.9;s.vy*=.9;s.rot+=s.vr*dt;s.life-=dt;if(s.life<=0)P.shells.splice(i,1);}
+  for(let i=G.floats.length-1;i>=0;i--){const f=G.floats[i];f.y-=34*dt;f.life-=dt;if(f.life<=0)G.floats.splice(i,1);}
+  // wave clear?
+  if(!G.spawnQueue.length&&G.enemies.length===0&&!G.extractActive){
+    if(G.wave<G.maxWaves){G.waveDelay+=dt;if(G.waveDelay>2.2){G.waveDelay=0;startWave(G.wave+1);P.reserve=Math.min(180,P.reserve+40);toast('+40 reserve ammo');}}
+    else{G.extractActive=true;banner('EXTRACTION','GET TO GREEN ZONE');SFX.extract();$('obj-text').textContent='All waves cleared — reach EXTRACTION';feed('☰ Extraction zone active (south)');}
+  }
+  // extraction win
+  if(G.extractActive&&P.x>extractZone.x&&P.x<extractZone.x+extractZone.w&&P.y>extractZone.y&&P.y<extractZone.y+extractZone.h){endGame(true);}
+  // camera + shake
+  const targetZoom=P.ads?1.12:1;
+  cam.zoom+=(targetZoom-cam.zoom)*Math.min(1,dt*8);
+  // camera in world coords: we render with scale; keep simple: cam = top-left in world
+  const viewW=W/cam.zoom,viewH=H/cam.zoom;
+  let tx=P.x-viewW/2+(mouse.x-W/2)*.08, ty=P.y-viewH/2+(mouse.y-H/2)*.08;
+  tx=Math.max(0,Math.min(WORLD.w-viewW,tx));ty=Math.max(0,Math.min(WORLD.h-viewH,ty));
+  cam.x+=(tx-cam.x)*Math.min(1,dt*7);cam.y+=(ty-cam.y)*Math.min(1,dt*7);
+  G.shake=Math.max(0,G.shake-dt*22);
+  $('dmg-vignette').style.opacity=Math.min(.9,Math.max(0,(1-P.hp/P.maxhp)*.9));
+}
+function damagePlayer(n,src){
+  if(!P.alive||G.mode!=='play')return;
+  P.hp-=n;P.lastHurt=G.time;G.shake=Math.min(10,G.shake+4);SFX.hurt();
+  blood(P.x,P.y,4);
+  if(P.hp<=0){P.hp=0;P.alive=false;endGame(false);}
+}
+function killEnemy(j){
+  const e=G.enemies[j];G.enemies.splice(j,1);G.kills++;
+  SFX.kill();hitmarker(true);blood(e.x,e.y,14);
+  floatText(e.x,e.y-26,'+1 KILL','#7CFFB2');
+  feed(e.type==='rush'?'☠ Rusher neutralized':'☠ Trooper neutralized');
+  G.shake=Math.min(8,G.shake+2);
+}
+
+// ---------- Render ----------
+function render(dt){
+  ctx.clearRect(0,0,W,H);
+  ctx.save();
+  const sx=(Math.random()-.5)*G.shake,sy=(Math.random()-.5)*G.shake;
+  ctx.translate(W/2,H/2);ctx.scale(cam.zoom,cam.zoom);ctx.translate(-W/2,-H/2);
+  ctx.translate(-cam.x+ -0 + 0,-cam.y);ctx.translate(sx,sy);
+  // floor
+  const g=ctx.createLinearGradient(0,0,0,WORLD.h);g.addColorStop(0,'#0d141c');g.addColorStop(1,'#0a1118');
+  ctx.fillStyle=g;ctx.fillRect(0,0,WORLD.w,WORLD.h);
+  // grid
+  ctx.strokeStyle='rgba(124,255,178,.06)';ctx.lineWidth=1;
+  ctx.beginPath();
+  for(let x=0;x<=WORLD.w;x+=60){ctx.moveTo(x,0);ctx.lineTo(x,WORLD.h);}
+  for(let y=0;y<=WORLD.h;y+=60){ctx.moveTo(0,y);ctx.lineTo(WORLD.w,y);}
+  ctx.stroke();
+  // world border
+  ctx.strokeStyle='rgba(124,255,178,.35)';ctx.lineWidth=3;ctx.setLineDash([14,10]);ctx.strokeRect(6,6,WORLD.w-12,WORLD.h-12);ctx.setLineDash([]);
+  // extraction
+  if(G.extractActive){const t=performance.now()/400;
+    ctx.fillStyle=`rgba(61,220,132,${.14+Math.sin(t)*.05})`;ctx.fillRect(extractZone.x,extractZone.y,extractZone.w,extractZone.h);
+    ctx.strokeStyle='#3ddc84';ctx.lineWidth=3;ctx.setLineDash([10,8]);ctx.lineDashOffset=-t*8;ctx.strokeRect(extractZone.x,extractZone.y,extractZone.w,extractZone.h);ctx.setLineDash([]);
+    ctx.fillStyle='#3ddc84';ctx.font='bold 15px sans-serif';ctx.textAlign='center';ctx.fillText('▼ EXTRACTION ▼',extractZone.x+extractZone.w/2,extractZone.y-10);
+  }
+  // obstacles (crates)
+  for(const o of obstacles){
+    ctx.fillStyle='#182430';ctx.fillRect(o.x,o.y,o.w,o.h);
+    ctx.fillStyle='#1f2f40';ctx.fillRect(o.x,o.y,o.w,8);
+    ctx.strokeStyle='rgba(124,255,178,.25)';ctx.lineWidth=2;ctx.strokeRect(o.x,o.y,o.w,o.h);
+    ctx.strokeStyle='rgba(255,255,255,.06)';ctx.beginPath();ctx.moveTo(o.x,o.y);ctx.lineTo(o.x+o.w,o.y+o.h);ctx.moveTo(o.x+o.w,o.y);ctx.lineTo(o.x,o.y+o.h);ctx.stroke();
+  }
+  // shells
+  ctx.fillStyle='#d8b25a';for(const s of P.shells){ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.rot);ctx.fillRect(-3,-1,6,2);ctx.restore();}
+  // enemy bullets
+  for(const b of G.ebullets){ctx.fillStyle='#ff7a7a';ctx.shadowColor='#ff3b3b';ctx.shadowBlur=8;ctx.beginPath();ctx.arc(b.x,b.y,3.5,0,7);ctx.fill();ctx.shadowBlur=0;}
+  // player bullets (tracers)
+  for(const b of G.bullets){ctx.strokeStyle='rgba(255,230,150,.95)';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(b.x-b.vx*.02,b.y-b.vy*.02);ctx.lineTo(b.x,b.y);ctx.stroke();}
+  // enemies
+  for(const e of G.enemies){
+    const a=Math.atan2(P.y-e.y,P.x-e.x);
+    ctx.save();ctx.translate(e.x,e.y);
+    // shadow
+    ctx.fillStyle='rgba(0,0,0,.4)';ctx.beginPath();ctx.ellipse(2,4,e.r,e.r*.7,0,0,7);ctx.fill();
+    ctx.rotate(a);
+    ctx.fillStyle=e.type==='rush'?'#ff6b5e':'#c77dff';
+    // gun/body
+    if(e.type==='rush'){ctx.fillRect(4,-5,14,10);}else{ctx.fillRect(6,-3,20,6);}
+    ctx.restore();
+    ctx.save();ctx.translate(e.x,e.y);ctx.rotate(a);
+    ctx.fillStyle=e.flash>0?'#fff':(e.type==='rush'?'#a3271f':'#5b2a86');
+    ctx.beginPath();ctx.arc(0,0,e.r,0,7);ctx.fill();
+    ctx.fillStyle='#0a0e14';ctx.beginPath();ctx.arc(5,0,5,0,7);ctx.fill();
+    ctx.restore();
+    // hp bar
+    ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(e.x-16,e.y-e.r-12,32,5);
+    ctx.fillStyle=e.type==='rush'?'#ff6b5e':'#c77dff';ctx.fillRect(e.x-16,e.y-e.r-12,32*(e.hp/e.maxhp),5);
+  }
+  // player
+  if(P.alive){
+    ctx.save();ctx.translate(P.x,P.y);
