+    ctx.rotate(P.angle);
+    if(P.muzzle>0){ctx.fillStyle='rgba(255,220,120,.95)';ctx.shadowColor='#ffb300';ctx.shadowBlur=18;ctx.beginPath();ctx.arc(30,0,9+Math.random()*5,0,7);ctx.fill();ctx.shadowBlur=0;}
+    // rifle
+    ctx.fillStyle='#0c0f14';ctx.fillRect(8,-3.5,26,7);ctx.fillStyle='#2b3b4f';ctx.fillRect(24,-2,10,4);
+    // body (tactical teal)
+    ctx.fillStyle='#123b33';ctx.strokeStyle='#7CFFB2';ctx.lineWidth=2.5;
+    ctx.beginPath();ctx.arc(0,0,P.r,0,7);ctx.fill();ctx.stroke();
+    // facing wedge
+    ctx.fillStyle='#7CFFB2';ctx.beginPath();ctx.arc(4,0,5,-.6,.6);ctx.lineTo(10,0);ctx.fill();
