+  mmc.clearRect(0,0,150,100);
+  mmc.fillStyle='rgba(10,16,24,.9)';mmc.fillRect(0,0,150,100);
+  const sx=150/WORLD.w,sy=100/WORLD.h;
+  mmc.fillStyle='rgba(124,255,178,.15)';
+  for(const o of obstacles)mmc.fillRect(o.x*sx,o.y*sy,o.w*sx,o.h*sy);
+  if(G.extractActive){mmc.fillStyle='#3ddc84';mmc.fillRect(extractZone.x*sx,extractZone.y*sy,extractZone.w*sx,extractZone.h*sy);}
+  for(const e of G.enemies){mmc.fillStyle=e.type==='rush'?'#ff6b5e':'#c77dff';mmc.beginPath();mmc.arc(e.x*sx,e.y*sy,2.4,0,7);mmc.fill();}
+  mmc.fillStyle='#7CFFB2';mmc.beginPath();mmc.arc(P.x*sx,P.y*sy,3,0,7);mmc.fill();
+  mmc.strokeStyle='rgba(255,255,255,.2)';mmc.strokeRect(.5,.5,149,99);
+}
+function updateHUD(){
+  $('hp-num').textContent=Math.ceil(P.hp);
+  const hf=$('hp-fill');hf.style.width=(P.hp/P.maxhp*100)+'%';hf.classList.toggle('low',P.hp<35);
+  $('stam-fill').style.width=P.stam+'%';
+  $('ammo-mag').textContent=P.mag;$('ammo-res').textContent='/ '+P.reserve;
+  $('kills').textContent=G.kills;$('timer').textContent=fmtTime(G.time);
+  const total=G.enemies.length+G.spawnQueue.length;
+  if(!G.extractActive)$('obj-sub').textContent=`Hostiles remaining: ${total} · Wave ${G.wave}/${G.maxWaves}`;
+  else $('obj-sub').textContent='Extraction active — move south, stay alive!';
+  const cleared=(G.wave-1)/G.maxWaves + (G.wave<=G.maxWaves? (1-total/Math.max(1,(waveComp(G.wave).rush+waveComp(G.wave).troop)))/G.maxWaves*0.9:0);
+  $('wavefill').style.width=Math.min(100,(G.extractActive?100:cleared*100))+'%';
+}
+requestAnimationFrame(loop);
+</script>
+</body>
+</html>

