function drawEdgeIndicators(){
  if(G.mode!=='play')return;
  const w2t=screenToWorld(mouse.x,mouse.y);
  // off-screen enemies: red chevrons clamped to screen edges
  ctx.save();ctx.textAlign='center';ctx.font='bold 14px sans-serif';
  for(const e of G.enemies){
    const sx=(e.x-cam.cx)*cam.zoom+W/2, sy=(e.y-cam.cy)*cam.zoom+H/2;
    if(sx>-20&&sx<W+20&&sy>-20&&sy<H+20)continue;
    const cx=Math.max(24,Math.min(W-24,sx)), cy=Math.max(64,Math.min(H-64,sy));
    const a=Math.atan2(sy-cy,sx-cx)||Math.atan2(e.y-P.y,e.x-P.x);
    ctx.fillStyle=e.type==='rush'?'rgba(255,107,94,.95)':'rgba(199,125,255,.95)';
    ctx.save();ctx.translate(cx,cy);ctx.rotate(a);
    ctx.beginPath();ctx.moveTo(10,0);ctx.lineTo(-5,-7);ctx.lineTo(-5,7);ctx.closePath();ctx.fill();
    ctx.restore();
  }
  // extraction compass: green arrow toward zone when active
  if(G.extractActive){
    const ex=extractZone.x+extractZone.w/2, ey=extractZone.y+extractZone.h/2;
    const dx=ex-P.x, dy=ey-P.y, d=Math.hypot(dx,dy);
    if(d>60){
      const a=Math.atan2(w2t.y-P.y,w2t.x-P.x); // relative to aim not needed; use zone dir:
      const za=Math.atan2(dy,dx);
      const px=W/2+Math.cos(za)*120, py=H/2+Math.sin(za)*120;
      ctx.fillStyle='#3ddc84';ctx.save();ctx.translate(px,py);ctx.rotate(za);
      ctx.beginPath();ctx.moveTo(14,0);ctx.lineTo(-6,-9);ctx.lineTo(-6,9);ctx.closePath();ctx.fill();
      ctx.restore();
      ctx.fillStyle='#3ddc84';ctx.font='bold 11px sans-serif';
      ctx.fillText('EXTRACTION '+Math.round(d/50)+'m', px, py-16);
    }
  }
  ctx.restore();
}

